import {preferences,defaultPreferences,profileLabel,type Preferences} from './preferences';
export type Ingredient = { name: string; qty: number; unit: string; category: string };
export type Recipe = { id: string; name: string; kind: 'breakfast'|'dal'|'curry'|'bhaja'|'grain'; protein: 'veg'|'fish'|'chicken'|'mutton'; minutes: number; ingredients: Ingredient[]; steps: string[]; note: string; allergens: string[]; englishName?:string; cuisine?:string };
const i=(name:string,qty:number,unit='g',category='Vegetables'):Ingredient=>({name,qty,unit,category});
const oil=(n=10)=>i('Cooking oil',n,'ml','Pantry');
const salt=(n=1)=>i('Salt',n,'g','Pantry');
const spice=(name:string,n=.5)=>i(name,n,'tsp','Pantry');
const onion=()=>i('Onion',150);
const tomato=()=>i('Tomato',200);
const ginger=()=>i('Ginger',15);
const garlic=()=>i('Garlic',15);
const lentil=(name:string,n=240)=>i(name,n,'g','Grains & pulses');
const dairy=(name:string,n:number)=>i(name,n,'g','Dairy & eggs');
const vegNote='Keep chillies optional. Cook until tender; offer soft, bite-sized pieces to younger children.';
const base=(id:string,name:string,kind:Recipe['kind'],minutes:number,ingredients:Ingredient[],steps:string[],note=vegNote,protein:Recipe['protein']='veg',allergens:string[]=[]):Recipe=>({id,name,kind,minutes,ingredients,steps,note,protein,allergens});
function dal(id:string,name:string,pulse:string,vegetable:string){return base(id,name,'dal',pulse==='Chana dal'||pulse==='Toor dal'?45:35,[lentil(pulse),i(vegetable,450),ginger(),oil(),salt(),spice('Cumin seeds'),spice('Turmeric',.5)],['Rinse the dal. Simmer with 1.2 litres water and turmeric until soft, adding water as needed. Chana or toor dal may take 45 minutes.','Add chopped vegetables and cook until tender. Stir often; mash lightly for a soft texture.','Warm the measured oil, bloom cumin and ginger, then stir into the dal. Add the measured salt and simmer for 3 minutes.']);}
function bhaja(id:string,name:string,vegetable:string){return base(id,name,'bhaja',25,[i(vegetable,900),oil(15),salt(.5),spice('Turmeric',.5),spice('Cumin seeds')],['Wash, dry and slice the vegetables. For okra, dry thoroughly before cutting.','Warm the measured oil in a wide nonstick pan and add cumin. Add vegetables and turmeric; cook in batches if crowded.','Cook on medium heat, turning often, until tender and lightly browned, about 15–20 minutes. Use a splash of water if sticking. Add measured salt. No deep frying.']);}
function vegCurry(id:string,name:string,ingredients:Ingredient[],steps:string[],allergens:string[]=[]){return base(id,name,'curry',35,[...ingredients,onion(),tomato(),ginger(),garlic(),oil(15),salt(),spice('Cumin seeds'),spice('Turmeric',.5),spice('Coriander powder',1)],['Heat the measured oil. Add cumin, chopped onion, ginger and garlic. Cook gently for 5 minutes. Add tomato, turmeric and coriander; cook until soft.',...steps,'Add measured salt and simmer until tender. Keep the gravy loose; add water as needed.'],vegNote,'veg',allergens);}
const fishNote='Cook fish to 63°C at its thickest point. Carefully remove all bones before serving children or anyone with chewing difficulty. Mustard can cause allergy.';
const chickenNote='Cook chicken to 74°C at its thickest point. Keep raw meat separate from ready-to-eat food. Remove bones and shred for young children.';
function fish(id:string,name:string,extra:Ingredient[],method:string){return base(id,name,'curry',35,[i('Fish (rui or boneless white fish)',900,'g','Fish & meat'),...extra,ginger(),oil(15),salt(),spice('Turmeric',.5),spice('Cumin seeds')],['Pat fish dry and rub with turmeric. Heat measured oil and cumin in a wide pan; add ginger.',method,'Slide in fish and simmer gently 10–15 minutes, until the thickest part reaches 63°C. Add measured salt. Debone each child’s portion carefully.'],fishNote,'fish',['Fish',...(id==='shorshe-fish'?['Mustard']:[])]);}
