export const substitutions:Record<string,string>={
 'Bottle gourd':'Use the same weight of courgette or ridge gourd. Cooking time may be shorter.',
 'Spinach':'Use amaranth leaves in the same weight; cook until soft.',
 'Green beans':'Use the same weight of carrot or cauliflower; cook until tender.',
 'Cauliflower':'Use broccoli in the same weight; start checking tenderness earlier.',
 'Pointed gourd':'Use courgette in the same weight; it cooks more quickly.',
 'Fenugreek leaves':'Use spinach in the same weight. The flavour will be milder.',
 'Paneer':'Use the same weight of firm tofu if tolerated. Tofu contains soy; paneer contains milk.',
 'Tofu':'Use the same weight of paneer if tolerated. Paneer contains milk.',
 'Fish (rui or boneless white fish)':'Use boneless rohu, bhetki or another white fish in the same weight. Cook to 63°C. For chicken, choose a chicken recipe instead.',
 'Split moong dal':'Use red masoor dal in the same dry weight. Check tenderness from 20 minutes; adjust water.',
 'Red masoor dal':'Use split moong dal in the same dry weight; allow longer cooking until soft.',
 'Cooked chickpeas, unsalted':'Use the same weight of fully cooked unsalted kidney beans; never swap in raw beans.',
 'Mustard seeds':'For a mustard allergy, choose another dish. Removing mustard changes sarson fish curry substantially.',
 'Plain unsweetened curd':'Use an unsweetened fortified soy yoghurt if tolerated; check the pack for added sugar and allergens.'
};
