// Display names use familiar Hindi words in English letters, not Bengali transliterations.
const displayNames:Record<string,string>={
 'lau-moong':'Lauki moong dal','masoor':'Tomato masoor dal','palong-dal':'Palak masoor dal','lebu-dal':'Nimbu moong dal','cholar':'Chana dal with vegetables','rui-jhol':'Rohu fish curry','shorshe-fish':'Sarson fish curry','doi-fish':'Dahi fish curry','tomato-fish':'Tomato dhaniya fish curry','chicken-jhol':'Light chicken curry','palong-chicken':'Palak chicken','doi-chicken':'Dahi chicken','soy':'Soya vegetable curry','mutton':'Light mutton curry','begun':'Baingan pan-fry','bhindi':'Bhindi pan-fry','beans':'Beans pan-fry','cabbage-bhaja':'Patta gobi pan-fry','fulkopi-bhaja':'Gobi pan-fry','carrot-bhaja':'Gajar jeera pan-fry','potol':'Parwal pan-fry','courgette':'Courgette pan-fry','pumpkin-bhaja':'Kaddu pan-fry','radish-bhaja':'Mooli pan-fry','bitter-gourd':'Karela pan-fry','ridge-gourd':'Turai pan-fry','mushroom-bhaja':'Mushroom pan-fry','capsicum-bhaja':'Shimla mirch pan-fry','beetroot-bhaja':'Chukandar pan-fry','broccoli-bhaja':'Broccoli pan-fry'};
const hindiIngredients:Record<string,string>={'Bottle gourd':'Lauki (bottle gourd)','Spinach':'Palak (spinach)','Fenugreek leaves':'Methi leaves','Aubergine':'Baingan (aubergine)','Okra':'Bhindi (okra)','Cauliflower':'Gobi (cauliflower)','Cabbage':'Patta gobi (cabbage)','Carrot':'Gajar (carrot)','Pumpkin':'Kaddu (pumpkin)','Radish':'Mooli (radish)','Pointed gourd':'Parwal (pointed gourd)','Ridge gourd':'Turai (ridge gourd)','Bitter gourd':'Karela (bitter gourd)','Capsicum':'Shimla mirch (capsicum)','Beetroot':'Chukandar (beetroot)','Green peas':'Matar (green peas)','Onion':'Pyaz (onion)','Tomato':'Tamatar (tomato)','Garlic':'Lahsun (garlic)','Ginger':'Adrak (ginger)','Cucumber':'Kheera (cucumber)','Fresh coriander':'Hara dhaniya (coriander)','Lemon':'Nimbu (lemon)','Fish (rui or boneless white fish)':'Rohu or boneless white fish','Thick poha (chire)':'Thick poha','Plain unsweetened curd':'Plain dahi (unsweetened curd)'};
for(const r of recipes){
 r.englishName=r.name;
 r.name=displayNames[r.id]||r.name.replaceAll('Palong','Palak').replaceAll('palong','palak').replaceAll('Kumro','Kaddu').replaceAll('kumro','kaddu').replaceAll('Fulkopi','Gobi').replaceAll('fulkopi','gobi').replaceAll('Begun','Baingan').replaceAll('begun','baingan').replaceAll('Potol','Parwal').replaceAll('Mulo','Mooli').replaceAll('Jhinge','Turai').replaceAll(' bhaja',' pan-fry').replaceAll(' pan-bhaja',' pan-fry');
 for(const ing of r.ingredients)ing.name=hindiIngredients[ing.name]||ing.name;
 // Combine duplicate ingredients within a recipe (e.g. two additions of tomato or besan).
 const merged=new Map<string,Ingredient>();for(const ing of r.ingredients){const key=ing.name+'|'+ing.unit;const old=merged.get(key);if(old)old.qty+=ing.qty;else merged.set(key,{...ing});}r.ingredients=[...merged.values()];
}
for(const [oldName,newName] of Object.entries(hindiIngredients))if(substitutions[oldName]){substitutions[newName]=substitutions[oldName];delete substitutions[oldName];}
for(const r of recipes){const names=r.ingredients.map(i=>i.name.toLowerCase()).join(' ');for(const [tag,re] of Object.entries({Milk:/paneer|curd|yoghurt|(?<!coconut )milk/,Egg:/\beggs?\b/,Wheat:/wheat|bread|dalia|semolina/,Gluten:/wheat|bread|dalia|semolina|barley/,Soy:/tofu|soya|soy /,Mustard:/mustard|sarson/,Coconut:/coconut/,Fish:/fish/})){if(re.test(names)&&!r.allergens.includes(tag))r.allergens.push(tag);}}
export const byId=Object.fromEntries(recipes.map(r=>[r.id,r])) as Record<string,Recipe>;
export type Meal='breakfast'|'lunch'|'dinner';
export type Plan={date:string; breakfast:string[]; lunch:string[]; dinner:string[]; confirmed:boolean; vegetarian:boolean;preferences?:Preferences;sharedCurry?:boolean;takeout?:Meal[];orders?:Partial<Record<Meal,string>>};
export type State={plans:Record<string,Plan>; pantry:Record<string,string[]>; settings:{phone1:string;phone2:string;allowMutton:boolean;preferences?:Preferences};revision:number};
export const emptyState=():State=>({plans:{},pantry:{},settings:{phone1:'',phone2:'',allowMutton:false,preferences:{...defaultPreferences}},revision:0});
export function indiaDate(offset=0,now=new Date()){const date=new Date(now.getTime()+offset*86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);}
export function addDay(date:string,offset:number){return new Date(Date.parse(date+'T12:00:00Z')+offset*86400000).toISOString().slice(0,10);}
export function dateLabel(date:string){return new Date(date+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',timeZone:'Asia/Kolkata'});}
const allIds=(p:Plan)=>[...p.breakfast,...p.lunch,...p.dinner];
export const cookedIds=(p:Plan)=>(['breakfast','lunch','dinner'] as Meal[]).filter(m=>!p.takeout?.includes(m)).flatMap(m=>p[m]);
export const batchCount=(p:Plan,id:string)=>cookedIds(p).filter(v=>v===id).length;
export function batchRecipe(p:Plan,r:Recipe,prefs:Preferences=p.preferences||defaultPreferences):Recipe{const count=Math.max(1,batchCount(p,r.id));const factor=count*prefs.servings/6;return {...r,ingredients:r.ingredients.map(i=>({...i,qty:Math.round(i.qty*factor*(i.name==='Cooking oil'?prefs.oilFactor:i.name==='Salt'?prefs.saltFactor:1)*100)/100})),steps:count>1?[`Make one ${count}× batch for lunch and dinner. The ingredients below are already scaled. Use a larger pot; scale recipe water ${+factor.toFixed(2)}× too and adjust to consistency. Cooking may take longer; check doneness.`,...r.steps]:[`Ingredient quantities are scaled to ${prefs.servings} family servings for one meal. Scale recipe water ${+(prefs.servings/6).toFixed(2)}× too; adjust cooking time and check doneness.`,...r.steps]};}
export function proteinForDate(date:string,prefs:Preferences=defaultPreferences):Recipe['protein']{return prefs.diet==='mixed'?prefs.weeklyProteins[new Date(date+'T12:00:00Z').getUTCDay()]:'veg';}
export function allowedRecipe(r:Recipe,p:Preferences){return (r.kind==='grain'||p.cuisines.includes(r.cuisine as Preferences['cuisines'][number]))&&(p.diet==='mixed'||r.protein==='veg')&&(p.diet!=='vegetarian'||!r.allergens.includes('Egg'))&&!r.allergens.some(a=>p.allergies.includes(a as Preferences['allergies'][number]))&&!p.avoidIngredients.some(term=>r.ingredients.some(i=>i.name.toLowerCase().includes(term.toLowerCase())));}
export function recipeName(r:Recipe,p:Preferences){if(p.language==='hindi')return r.name;const words:Record<string,string>={palak:'spinach',saag:'greens',lauki:'bottle gourd',gobi:'cauliflower',baingan:'aubergine',bhindi:'okra',gajar:'carrot',kaddu:'pumpkin',mooli:'radish',karela:'bitter gourd',parwal:'pointed gourd',methi:'fenugreek',matar:'peas',sarson:'mustard',dahi:'yoghurt',dhaniya:'coriander',nimbu:'lemon',imli:'tamarind',chana:'chickpea',rajma:'kidney bean',moong:'mung',paneer:'paneer',dal:'lentils'};const text=r.name.replace(/patta gobi/gi,'cabbage').replace(/\b(palak|saag|lauki|gobi|baingan|bhindi|gajar|kaddu|mooli|karela|parwal|methi|matar|sarson|dahi|dhaniya|nimbu|imli|chana|rajma|moong|dal)\b/gi,w=>words[w.toLowerCase()]||w);return text[0].toUpperCase()+text.slice(1);}

function hash(value:string){let h=0;for(const ch of value)h=(h*31+ch.charCodeAt(0))>>>0;return h;}
function choose(kind:Recipe['kind'],date:string,state:State,used:string[],veg:boolean,saltKey:string,protein?:Recipe['protein']):string{
 const prefs=preferences(state);
 const recent=Object.values(state.plans).filter(p=>Math.abs(Date.parse(p.date)-Date.parse(date))<20*86400000);
 const muttonUsed=recent.filter(p=>Math.abs(Date.parse(p.date)-Date.parse(date))<14*86400000).some(p=>allIds(p).some(id=>byId[id].protein==='mutton'));
 // Reserve planned home recipes too, so restoring an order-in meal keeps weekly variety intact.
 const weekly=new Set(recent.filter(p=>p.date!==date&&Math.abs(Date.parse(p.date)-Date.parse(date))<prefs.repeatDays*86400000).flatMap(allIds));
 const candidates=recipes.filter(r=>r.kind===kind&&allowedRecipe(r,prefs)&&!used.includes(r.id)&&!weekly.has(r.id)&&(!veg||r.protein==='veg'&&!r.allergens.includes('Egg'))&&(!protein||r.protein===protein)&&(r.protein!=='mutton'||state.settings.allowMutton&&!muttonUsed));
 if(!candidates.length)throw new Error('No unused recipe fits all preferences. Try more cuisines, a shorter repeat window, or fewer ingredient exclusions. Your saved menu has not changed.');
 const cuisineCycle=['Punjabi','South Indian','Italian-inspired','Bengali','French-inspired','North Indian','Asian-inspired','English-inspired'];
 const activeCuisines=cuisineCycle.filter(c=>prefs.cuisines.includes(c as Preferences['cuisines'][number]));
 const target=activeCuisines[Math.floor(Date.parse(date)/86400000)%activeCuisines.length];
 const score=(r:Recipe)=>recent.reduce((n,p)=>n+(allIds(p).includes(r.id)?1000/(1+Math.abs(Date.parse(p.date)-Date.parse(date))/86400000):0),0)+(hash(date+saltKey+r.id)%100)/100+(r.cuisine===target?-40:0);
 return candidates.sort((a,b)=>score(a)-score(b))[0].id;
}
export function generatePlan(date:string,state:State,vegetarian=false):Plan{
 const prefs=preferences(state);
 const used:string[]=[];const weekday=new Date(date+'T12:00:00Z').getUTCDay();
 const pick=(kind:Recipe['kind'],protein?:Recipe['protein'])=>{const id=choose(kind,date,state,used,vegetarian,String(used.length),protein);used.push(id);return id;};
 const breakfast=[pick('breakfast')];let protein=vegetarian?'veg' as const:proteinForDate(date,prefs);
 const recentMutton=Object.values(state.plans).some(p=>Math.abs(Date.parse(p.date)-Date.parse(date))<14*86400000&&allIds(p).some(id=>byId[id].protein==='mutton'));
 if(prefs.diet==='mixed'&&!vegetarian&&weekday===0&&state.settings.allowMutton&&!recentMutton)protein='mutton';
 const curry=pick('curry',protein);
 for(const grain of [prefs.lunchStaple,prefs.dinnerStaple])if(!allowedRecipe(byId[grain],prefs))throw new Error('The selected staple conflicts with an ingredient or allergy restriction. Choose another staple.');
 const lunch=[prefs.lunchStaple,...(prefs.includeDal?[pick('dal')]:[]),curry,...(prefs.includeSide?[pick('bhaja')]:[])];
 const dinner=[prefs.dinnerStaple,...(prefs.includeDal?[pick('dal')]:[]),prefs.sharedCurry?curry:pick('curry',protein),...(prefs.includeSide?[pick('bhaja')]:[])];
 return {date,breakfast,lunch,dinner,confirmed:false,vegetarian,preferences:{...prefs},sharedCurry:prefs.sharedCurry,takeout:state.plans[date]?.takeout||[],orders:state.plans[date]?.orders||{}};
}
export function alternatives(plan:Plan,id:string,state:State):Recipe[]{
 const prefs=preferences(state);
 const original=byId[id];if(!original||original.kind==='grain')return [];
 const used=new Set(allIds(plan));
 for(const other of Object.values(state.plans))if(other.date!==plan.date&&Math.abs(Date.parse(other.date)-Date.parse(plan.date))<prefs.repeatDays*86400000)allIds(other).forEach(v=>used.add(v));
 const muttonUsed=Object.values(state.plans).filter(p=>Math.abs(Date.parse(p.date)-Date.parse(plan.date))<14*86400000).some(p=>allIds(p).some(v=>byId[v].protein==='mutton'));
 return recipes.filter(r=>r.kind===original.kind&&allowedRecipe(r,prefs)&&!used.has(r.id)&&(!plan.vegetarian||r.protein==='veg'&&!r.allergens.includes('Egg'))&&(r.kind!=='curry'||r.protein===original.protein)&&(r.protein!=='mutton'||state.settings.allowMutton&&!muttonUsed));
}
export function swapRecipe(plan:Plan,id:string,state:State,replacement?:string):Plan{
 if(plan.confirmed)throw new Error('Unlock this menu before making changes.');
 const recipe=byId[id];if(!recipe||!allIds(plan).includes(id)||recipe.kind==='grain')throw new Error('This dish cannot be swapped.');
 const options=alternatives(plan,id,state);
 if(replacement&&!options.some(r=>r.id===replacement))throw new Error('This alternative conflicts with the weekly variety or protein plan.');
 const next=replacement||options[0]?.id;if(!next)throw new Error('No unused alternative fits this week.');
 return {...plan,breakfast:plan.breakfast.map(v=>v===id?next:v),lunch:plan.lunch.map(v=>v===id?next:v),dinner:plan.dinner.map(v=>v===id?next:v)};
}
export function shopping(plan:Plan,prefs:Preferences=plan.preferences||defaultPreferences):Ingredient[]{const map=new Map<string,Ingredient>();for(const id of cookedIds(plan)){for(const ing of byId[id].ingredients){const key=ing.name+'|'+ing.unit;const item=map.get(key);if(item)item.qty=Math.round((item.qty+ing.qty)*100)/100;else map.set(key,{...ing});}}return [...map.values()].map(i=>({...i,qty:Math.round(i.qty*prefs.servings/6*(i.name==='Cooking oil'?prefs.oilFactor:i.name==='Salt'?prefs.saltFactor:1)*100)/100})).filter(i=>i.qty>0).sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name));}
export const ingredientKey=(i:Ingredient)=>i.name+'|'+i.unit;
export const quantity=(i:Ingredient)=>i.unit==='g'&&i.qty>=1000?`${+(i.qty/1000).toFixed(2)} kg`:`${i.qty} ${i.unit}`;
export const batchSafety='Set aside the dinner portion in shallow containers and refrigerate within 2 hours (1 hour above 32°C), at 4°C or colder. Reheat only the portion needed to 74°C, until steaming hot throughout. Do not leave the afternoon curry on the stove until dinner.';
export function cookMessage(plan:Plan,pantry:string[]=[],includeRecipes=false,prefs:Preferences=plan.preferences||defaultPreferences){
 const list=shopping(plan,prefs).filter(i=>!pantry.includes(ingredientKey(i)));
 const lines=[`COOK BRO • ${dateLabel(plan.date)}`,`Menu for ${profileLabel(prefs)} · ${prefs.servings} family servings per meal`,plan.confirmed?'Confirmed menu':'Suggested menu',''];
 for(const meal of ['breakfast','lunch','dinner'] as Meal[])lines.push(meal.toUpperCase(),...(plan.takeout?.includes(meal)?['ORDERING IN: no home cooking for this meal.']:plan[meal].map(id=>'• '+recipeName(byId[id],prefs))),'');
 const shared=plan.lunch.find(id=>byId[id].kind==='curry'&&plan.dinner.includes(id));
 if(shared&&batchCount(plan,shared)>1)lines.push(`COOK ONCE: ${byId[shared].name} for lunch AND dinner. Quantities below include both meals.`,batchSafety,'');
 lines.push('TO BUY',...(list.length?list.map(i=>`• ${i.name}: ${quantity(i)}`):['No additional ingredients needed.']), '','COOK NOTES','No added sugar. Measure oil and salt as listed; no deep frying. Keep chilli separate. Remove fish bones; cook meat and eggs thoroughly. Serve soft pieces for children and elders. Quantities are starting amounts for the family; adjust to appetite.');
 if(cookedIds(plan).includes('chilla'))lines.push('Tonight: soak moong dal for breakfast in the fridge.');
 if(includeRecipes){lines.push('','RECIPES');for(const id of [...new Set(cookedIds(plan))]){const r=batchRecipe(plan,byId[id],prefs);lines.push('',recipeName(r,prefs)+(batchCount(plan,id)>1?' (one batch for both meals)':''),`Ingredients: ${r.ingredients.map(i=>i.name+' '+quantity(i)).join(', ')}`,...r.steps.map((s,n)=>`${n+1}. ${s}`),r.note);}}
 return lines.join('\n');
}
